const frame = msg.payload || msg;
const canId = frame.canid;
const data = frame.data || [];

let state = flow.get('batteryEnergyFlow') || {
    kind: 'BatteryEnergyFlowState',
    version: 1,
    bmsCount: 0,
    socPercent: null,
    sohPercent: null,
    voltageV: null,
    currentA: null,
    temperatureC: null,
    bmsList: []
};

function u16(buf, offset) {
    return (buf[offset] & 0xFF) | ((buf[offset + 1] & 0xFF) << 8);
}

function s16(buf, offset) {
    var val = u16(buf, offset);
    return val > 0x7FFF ? val - 0x10000 : val;
}

function getBms(addr) {
    var bms = state.bmsList.find(function(b) { return b.bmsAddress === addr; });
    if (!bms) {
        bms = { bmsAddress: addr };
        state.bmsList.push(bms);
        state.bmsList.sort(function(a, b) { return a.bmsAddress - b.bmsAddress; });
    }
    return bms;
}

var processed = false;

if (canId >= 0x351 && canId <= 0x35E) {
    processed = true;
    switch (canId) {
        case 0x355:
            state.socPercent = u16(data, 0);
            state.sohPercent = u16(data, 2);
            break;
        case 0x356:
            state.voltageV = s16(data, 0) * 0.01;
            state.currentA = s16(data, 2) * 0.1;
            state.temperatureC = s16(data, 4) * 0.1;
            break;
        case 0x359:
            state.bmsCount = data[4];
            break;
    }
}

if ((canId & 0x1FFFF000) === 0x14F00000) {
    processed = true;
    var msgType = (canId >> 8) & 0x0F;
    var bmsAddr = canId & 0xFF;
    var bms = getBms(bmsAddr);

    switch (msgType) {
        case 1:
            bms.chargeDischargeStatus = data[0];
            bms.currentA = s16(data, 2) * 0.1;
            bms.batteryPackVoltageV = u16(data, 4) * 0.1;
            bms.batteryRemainingCapacityAh = u16(data, 6) * 0.01;
            break;
        case 2:
            bms.maxCellVoltageMv = u16(data, 0);
            bms.minCellVoltageMv = u16(data, 2);
            bms.avgCellVoltageMv = u16(data, 4);
            bms.avgCellTempC = s16(data, 6) * 0.1;
            break;
        case 3:
            bms.ratedCapacityAh = u16(data, 0) * 0.01;
            bms.totalDischargeWh = u16(data, 4);
            bms.cycleCount = u16(data, 6);
            break;
        case 4:
            bms.sohPercent = u16(data, 2);
            break;
    }
}

if (!processed) {
    return null;
}

state.timestampUtc = new Date().toISOString();
state.DeviceId = global.get('GATEWAY_ID') || 'EC100';
flow.set('batteryEnergyFlow', state);
return null;

const frame = msg.payload || msg;
const canId = frame.canid;
const data = frame.data || [];

let state = flow.get('batteryInfo') || {
    kind: 'BatteryInfoState',
    version: 1,
    manufacturerName: null,
    moduleCount: 0,
    bmsList: []
};

function u16(buf, offset) {
    return (buf[offset] & 0xFF) | ((buf[offset + 1] & 0xFF) << 8);
}

function getBms(addr) {
    var bms = state.bmsList.find(function(b) { return b.bmsAddress === addr; });
    if (!bms) {
        bms = { bmsAddress: addr, _sn1: '', _sn2: '', _sn3: '' };
        state.bmsList.push(bms);
        state.bmsList.sort(function(a, b) { return a.bmsAddress - b.bmsAddress; });
    }
    return bms;
}

var processed = false;

if (canId === 0x359) {
    processed = true;
    state.moduleCount = data[4];
}

if (canId === 0x35E) {
    processed = true;
    var name = '';
    for (var i = 0; i < 8; i++) {
        if (data[i] === 0) break;
        name += String.fromCharCode(data[i]);
    }
    state.manufacturerName = name;
}

if ((canId & 0x1FFFF000) === 0x14F00000) {
    var msgType = (canId >> 8) & 0x0F;
    var bmsAddr = canId & 0xFF;

    if (msgType >= 3 && msgType <= 7) {
        processed = true;
        var bms = getBms(bmsAddr);

        switch (msgType) {
            case 3:
                bms.ratedCapacityAh = u16(data, 0) * 0.01;
                break;
            case 4:
                bms.softwareVersionMain = data[0];
                bms.softwareVersionSub = data[1];
                break;
            case 5:
                bms._sn1 = '';
                for (var j = 0; j < 8; j++) {
                    if (data[j] === 0) break;
                    bms._sn1 += String.fromCharCode(data[j]);
                }
                bms.serialNumber = bms._sn1 + (bms._sn2 || '') + (bms._sn3 || '');
                break;
            case 6:
                bms._sn2 = '';
                for (var k = 0; k < 8; k++) {
                    if (data[k] === 0) break;
                    bms._sn2 += String.fromCharCode(data[k]);
                }
                bms.serialNumber = (bms._sn1 || '') + bms._sn2 + (bms._sn3 || '');
                break;
            case 7:
                bms._sn3 = '';
                for (var l = 0; l < 8; l++) {
                    if (data[l] === 0) break;
                    bms._sn3 += String.fromCharCode(data[l]);
                }
                bms.serialNumber = (bms._sn1 || '') + (bms._sn2 || '') + bms._sn3;
                break;
        }
    }
}

if (!processed) {
    return null;
}

state.timestampUtc = new Date().toISOString();
state.DeviceId = global.get('GATEWAY_ID') || 'EC100';
flow.set('batteryInfo', state);
return null;

const state = flow.get('batteryEnergyFlow');

if (!state) {
    msg.payload = {
        error: 'No battery energy data available yet',
        kind: 'BatteryEnergyFlowState'
    };
    node.status({ fill: 'yellow', shape: 'ring', text: 'No data' });
} else {
    msg.payload = state;
    node.status({ fill: 'green', shape: 'dot', text: `SOC: ${state.socPercent}%` });
}

return msg;

const state = flow.get('batteryInfo');

if (!state) {
    msg.payload = {
        error: 'No battery info data available yet',
        kind: 'BatteryInfoState'
    };
    node.status({ fill: 'yellow', shape: 'ring', text: 'No data' });
} else {
    // Clean response - remove internal _sn fields
    const clean = JSON.parse(JSON.stringify(state));
    clean.bmsList.forEach(function(bms) {
        delete bms._sn1;
        delete bms._sn2;
        delete bms._sn3;
    });
    msg.payload = clean;
    node.status({ fill: 'green', shape: 'dot', text: `Modules: ${state.moduleCount}` });
}

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;

const method = msg.payload.method;
const params = msg.payload.params || {};

// Extract request ID from topic
const topicParts = msg.topic.split('/');
const requestId = topicParts[topicParts.length - 1];

msg.rpcMethod = method;
msg.rpcParams = params;
msg.rpcRequestId = requestId;
msg.rpcResponseTopic = `v1/devices/me/rpc/response/${requestId}`;

// Route based on method
if (method === 'getBatteryEnergyFlowState') {
    return [msg, null];
} else if (method === 'getBatteryInfoState') {
    return [null, msg];
}

// Unknown method
node.status({ fill: 'yellow', shape: 'ring', text: 'Unknown: ' + method });
return [null, null];
